import random

def check_graph(edges, n=14):
    """Check if a graph satisfies all constraints."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    degrees = [len(adj[i]) for i in range(n)]
    if min(degrees) < 4 or max(degrees) > 6:
        return False, degrees, None

    if len(edges) < 21 or len(edges) > 37:
        return False, degrees, None

    # Better chromatic number check using backtracking
    def can_color_with_k(adj, k):
        colors = [-1] * n
        def backtrack(v):
            if v == n:
                return True
            for c in range(k):
                valid = True
                for neighbor in adj[v]:
                    if neighbor < v and colors[neighbor] == c:
                        valid = False
                        break
                if valid:
                    colors[v] = c
                    if backtrack(v + 1):
                        return True
                    colors[v] = -1
            return False
        return backtrack(0)

    # Check if 3-colorable
    if can_color_with_k(adj, 3):
        chi = 3
    elif can_color_with_k(adj, 4):
        chi = 4
    else:
        chi = 5  # Need more than 4

    if chi < 3 or chi > 4:
        return False, degrees, chi

    return True, degrees, chi

